 import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const T = ctx.THREE;

  const group = new T.Group();
  group.userData.handlers = {};

  const atlasRect = (config.atlasRegion && config.atlasRegion.rect) ? config.atlasRegion.rect : [0, 0, 512, 320];
  const rectX = atlasRect[0];
  const rectY = atlasRect[1];
  const rectW = atlasRect[2];
  const rectH = atlasRect[3];
  const aspect = rectW / rectH;

  const width = 2.4;
  const height = width / aspect;

  const geometry = new T.PlaneGeometry(width, height, 1, 1);

  const fallbackColor = config.intent?.visualSpec?.colors?.surface || '#0b0b10';
  const material = new MeshBasicNodeMaterial({
    color: new T.Color(fallbackColor),
    side: T.DoubleSide,
    transparent: false
  });

  const mesh = new T.Mesh(geometry, material);
  mesh.visible = false;

  mesh.onBeforeRender = (renderer, scene, camera, geometry, material, group) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  group.add(mesh);

  const timelines = [];

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!group.parent && !mesh.parent) return;

      tex.colorSpace = T.SRGBColorSpace;

      const imgW = tex.image?.width || rectW;
      const imgH = tex.image?.height || rectH;

      tex.wrapS = T.ClampToEdgeWrapping;
      tex.wrapT = T.ClampToEdgeWrapping;
      tex.offset.set(rectX / imgW, rectY / imgH);
      tex.repeat.set(rectW / imgW, rectH / imgH);
      tex.needsUpdate = true;

      material.color.set('#ffffff');
      material.map = texture(tex);
      if (material.map && material.map.value !== undefined) material.map.value = tex;
      material.needsUpdate = true;
      mesh.visible = true;
    }).catch(() => {
      material.color.set(fallbackColor);
      mesh.visible = true;
    });
  } else {
    mesh.visible = true;
  }

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        const result = ctx.primitives[primitive.name](group, primitive.params || {});
        if (result && result.timeline) timelines.push(result.timeline);
      }
    }
  }

  group.userData.cleanup = () => {
    for (const tl of timelines) {
      if (tl && typeof tl.kill === 'function') tl.kill();
    }
    if (material.map) {
      try { material.map.dispose && material.map.dispose(); } catch (e) {}
    }
    material.dispose();
    geometry.dispose();
    group.remove(mesh);
  };

  return group;
}
